class ParkingPass {private final String holder; private final java.time.LocalDate expiry; ParkingPass(String h,java.time.LocalDate e){holder=h;expiry=e;} public boolean isValid(){return !java.time.LocalDate.now().isAfter(expiry);} public String getHolder(){return holder;}} public class Main {public static void main(String[]a){ParkingPass p=new ParkingPass("Student",java.time.LocalDate.now().plusDays(30));System.out.println(p.getHolder()+" pass valid="+p.isValid());}}
